    ExcelDB.WorldRaidConditionExcelTable.StartDataListVector(builder, len(offsets))
    for offset in reversed(offsets):
        builder.PrependUOffsetTRelative(offset)
    data_list = builder.EndVector()
    ExcelDB.WorldRaidConditionExcelTable.Start(builder)
    ExcelDB.WorldRaidConditionExcelTable.AddDataList(builder, data_list)
    return ExcelDB.WorldRaidConditionExcelTable.End(builder)

